, u1 as (update model_picks m set result=case when v.r='V' then null else v.r end, actual=case when v.a ~ '^-?[0-9.]+$' then v.a::numeric end, result_source='BettorDays grading from ESPN box scores', graded_at=now(), status=case when v.r='V' then 'void' else 'graded' end, updated_at=now()
  from v where m.slate_date='2026-11-24' and m.pick_text=v.p and m.status<>'void' returning 1)
, u2 as (update model_v7_legs l set result=case when v.r='V' then null else v.r end, actual=case when v.a ~ '^-?[0-9.]+$' then v.a::numeric end, graded_at=now() from v where l.slate_date='2026-11-24' and l.pick_text=v.p returning 1)
select (select count(*) from u1) picks_updated, (select count(*) from u2) v7_legs_updated;
